from pathlib import Path
import json,subprocess,sys,hashlib
R=Path(__file__).resolve().parent
for script in ['validate_model.py','check_all_layers.py','check_layer_components.py','check_thin_features.py','check_feature_losses.py','check_architectural_rays.py']:
 subprocess.run([sys.executable,str(R/script)],check=True)
v=json.loads((R/'validation.json').read_text());l=json.loads((R/'layer-opening-check.json').read_text());lc=json.loads((R/'layer-component-check.json').read_text());f=json.loads((R/'feature-loss-locations.json').read_text());a=json.loads((R/'architectural-ray-check.json').read_text())
checks={**v['checks'],**lc['checks'],**a['checks'],'all_validators_exit_zero':True,'all_original_sections_valid_without_repair':True,'canonical_v3_hash_matches':hashlib.sha256((R/'check_thin_features.py').read_bytes()).hexdigest()=='059f7378c74a1400dcf010365ebf35df3027fd853f1c960462a233dc68ce8915'}
report={'passed':all(checks.values()),'checks':checks,'layer_pitch_mm':.2,'layer_offset_mm':.071,'layer_count':l['sampled_layers'],'original_polygon_count':len(lc['original_component_checks']),'opening_reference_width_mm':.8,'maximum_whole_layer_loss_fraction':l['maximum_opening_loss_fraction'],'maximum_original_component_loss_fraction':f['maximum_original_component_loss_fraction'],'accepted_specific_corner_exception':{'physical_columns':22,'layer_samples':890,'bounds_corner_radius_mm':.41,'minimum_actual_normal_width_mm':min(min(r['actual_normal_x_mm'],r['actual_normal_y_mm']) for r in a['column_samples']),'scope':'Only documented 22 rectangular ground columns; not a global threshold relaxation or an exemption for thin skins.'},'stl_sha256':v['stl_sha256'],'warnings':['22 physical columns have 890 sampled corner-only losses over 1%; no disappearance/split, actual normals and upper/lower roots checked.','Not global wall thickness, slicing toolpaths or a physical print guarantee.','Exact building-specific height is not established.']}
(R/'qa-summary.json').write_text(json.dumps(report,ensure_ascii=False,indent=2));assert report['passed']
